-- Modify "products" table
ALTER TABLE `products` ADD COLUMN `product_kind` varchar(255) NOT NULL DEFAULT "standard";
-- Create "sms_retail_quotes" table
CREATE TABLE `sms_retail_quotes` (`id` varchar(64) NOT NULL, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `user_id` bigint unsigned NOT NULL, `product_id` bigint unsigned NOT NULL, `connection_id` bigint unsigned NOT NULL, `connection_identity` varchar(255) NOT NULL, `pricing_revision` varchar(255) NOT NULL, `product_revision` bigint NOT NULL, `upstream_quote_id` varchar(64) NOT NULL, `upstream_product_id` varchar(255) NOT NULL, `cost_cents` bigint NOT NULL, `amount_cents` bigint NOT NULL, `expires_at` bigint NOT NULL, `offer_name` varchar(255) NOT NULL, `selection` json NULL, `consumed_by` varchar(255) NOT NULL DEFAULT "", PRIMARY KEY (`id`), INDEX `smsretailquote_expires_at` (`expires_at`), INDEX `smsretailquote_subsite_id_user_id_product_id` (`subsite_id`, `user_id`, `product_id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
